package mz.bam.seeky.android;
import android.content.*;import android.database.sqlite.*;import java.nio.file.Files;
public final class TimerCheck {
 static int checks;interface Work{void run()throws Exception;}
 static void ok(boolean v,String n){if(!v)throw new AssertionError(n);checks++;System.out.println("PASS "+n);}
 static void fails(Work w,String n)throws Exception{try{w.run();throw new AssertionError(n);}catch(IllegalStateException|IllegalArgumentException|SQLiteException expected){ok(true,n);}}
 static Context context()throws Exception{return new Context(Files.createTempDirectory("seeky-timer-").toFile());}
 static String token(Context c){return FocusSessions.prefs(c).getString("timer_token","");}
 public static void main(String[] args)throws Exception{
  Context c=context();SharedPreferences p=FocusSessions.prefs(c);long e=10000,w=1000000;
  FocusSessions.start(c,"Chapter one",0,1,"Foco",e,w);String first=token(c);ok(p.getBoolean("timer_active",false)&&!p.getBoolean("timer_paused",true),"timer starts with durable active state");ok(!first.isEmpty(),"timer has a unique durable token");fails(()->FocusSessions.start(c,"Other",0,1,"Foco",e,w),"second active timer cannot replace current session");
  ok(FocusSessions.seconds(p,e+12000,w+12000)==12,"elapsed countdown does not depend on Activity ticks");FocusSessions.toggle(c,first,e+12000,w+12000);ok(p.getBoolean("timer_paused",false),"notification pause transition is persisted");ok(FocusSessions.seconds(p,e+90000,w+90000)==12,"paused time does not grow in background");FocusSessions.toggle(c,first,e+90000,w+90000);ok(FocusSessions.seconds(p,e+100000,w+100000)==22,"resume continues from accumulated seconds");
  ok(FocusSessions.seconds(p,1000,w+110000)==32,"reboot-style elapsed reset uses wall fallback");ok(FocusSessions.seconds(p,e+999999,w+999999)==60,"late delivery is capped to session duration");
  FocusSessions.Result done=FocusSessions.finish(c,first,false,e+999999,w+999999);ok(done.changed&&done.recorded&&done.seconds==60,"completion records bounded elapsed time");try(StudyStore db=new StudyStore(c)){ok(db.count("sessions",null,null)==1&&db.rows("sessions",null,null,null,1).get(0).n("seconds")==60,"session is durably stored once");}ok(!p.getBoolean("timer_active",true),"completed timer is inactive");
  FocusSessions.finish(c,first,false,e+1000000,w+1000000);try(StudyStore db=new StudyStore(c)){ok(db.count("sessions",null,null)==1,"duplicate completion cannot create duplicate session");}
  // Simulate process death after the DB committed but before preferences were cleared.
  p.edit().putBoolean("timer_active",true).commit();FocusSessions.Result recovered=FocusSessions.finish(c,first,false,e+1000000,w+1000000);ok(recovered.changed&&!recovered.recorded&&!p.getBoolean("timer_active",true),"crash reconciliation clears stale active state without another insert");
  FocusSessions.start(c,"New focus",0,2,"Foco",e+2000000,w+2000000);String second=token(c);ok(!second.equals(first),"each new session gets a different token");FocusSessions.finish(c,first,false,e+2005000,w+2005000);ok(p.getBoolean("timer_active",false)&&token(c).equals(second),"stale notification action cannot finish a newer session");FocusSessions.toggle(c,first,e+2005000,w+2005000);ok(!p.getBoolean("timer_paused",true),"stale action cannot pause a newer session");FocusSessions.finish(c,second,true,e+2010000,w+2010000);try(StudyStore db=new StudyStore(c)){ok(db.count("sessions",null,null)==1,"discard clears timer without adding study time");}
  FocusSessions.start(c,"Retry",0,1,"Foco",e+3000000,w+3000000);String retry=token(c);try(StudyStore db=new StudyStore(c)){db.getWritableDatabase().execSQL("CREATE TRIGGER reject_timer BEFORE INSERT ON sessions BEGIN SELECT RAISE(ABORT,'full disk');END");}fails(()->FocusSessions.finish(c,retry,false,e+3010000,w+3010000),"session write failure is reported");ok(p.getBoolean("timer_active",false),"failed session write leaves timer recoverable");try(StudyStore db=new StudyStore(c)){ok(db.count("sessions",null,null)==1,"failed session write commits no partial record");db.getWritableDatabase().execSQL("DROP TRIGGER reject_timer");}FocusSessions.finish(c,retry,false,e+3020000,w+3020000);try(StudyStore db=new StudyStore(c)){ok(db.count("sessions",null,null)==2,"retry records session after storage failure");}
  long module;try(StudyStore db=new StudyStore(c)){module=db.save("subjects",0,StudyStore.values("title","Module","color",1,"created",1));}FocusSessions.start(c,"Deleted module",module,1,"Foco",e+4000000,w+4000000);try(StudyStore db=new StudyStore(c)){db.deleteSubject(module);}FocusSessions.finish(c,token(c),false,e+4010000,w+4010000);try(StudyStore db=new StudyStore(c)){ok(db.rows("sessions",null,null,"id DESC",1).get(0).n("subject")==0,"deleted module retains elapsed time in General");}
  fails(()->FocusSessions.start(c,"Invalid",999,1,"Foco",e,w),"timer rejects a missing module");fails(()->FocusSessions.start(c,"Invalid",0,0,"Foco",e,w),"timer rejects invalid duration");
  System.out.println("PASS "+checks+" actual background timer persistence checks on host SQLite JDBC");
 }
}
